window.products.push({"id":423288,"name":"KC Kullicraft Marble Soapstone Red Floral Carving Candle Aroma Burner Oil Diffuser and Tea Light Holder for Home Décor and Living Decor","category":"homeandappliances","retail price":13.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/71n6hTUizFL._SL1500_.jpg","description":"Aromatherapy Artisan Handcarved Stone Oil Diffuser Burner with Tea Light Holder. Hand carved from soapstone by the artisans of rural India. This diffuser is delicately carved from Soapstone. Unique with a natural variation in color of the stone, Our artisans work tirelessly to bring to you perfectly carved pieces. All our products are sourced from traditional artisans from Indian villages who have been using time tested techniques in the handcrafting and this is our small effort to provide some highly needed support to these traditional arts and crafts that are facing a daily struggle to survive in todays world.","images":["https://m.media-amazon.com/images/I/71n6hTUizFL._SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"KC KULLICRAFT","source_asin":"B07YLM4K1M","category_path":"Home & Kitchen"},"sku":"BM-423288","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B07YLM4K1M","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B07YLM4K1M","price_pending":true,"merchant_ready":false});
